/**
 * Three DeepSeek AI Agents
 *
 * Agent 1 — CHAT: Client-facing assistant
 *   - Salon info, prices, booking, auth blocks, chat
 *   - Key: DEEPSEEK_API_KEY_CHAT
 *
 * Agent 2 — LANDING: Landing page + SEO generation
 *   - Newsletter landing pages, CMS blocks, SEO metadata
 *   - Key: API_KEY_NEWSLETTER_LANDING_GENERATION
 *
 * Agent 3 — IMAGE: Image prompt generation
 *   - Generates prompts → actual rendering via Google Gemini
 *   - Key: API_KEY_IMAGE_GENERATION
 *   - NOTE: DeepSeek does not support image generation natively.
 *     Image prompts are generated by DeepSeek, then passed to Gemini Imagen.
 */

export type AgentType =
  | "chat"
  | "landing"
  | "seo"
  | "image"
  | "campaignStrategy"
  | "campaignContent"
  | "campaignTemplate"
  | "campaignOptimization"
  | "seoLandingTheme"
  | "metadataSeo"
  | "ctaStrategy"
  | "landingContent";

export interface AgentConfig {
  type: AgentType;
  apiKey: string;
  model: string;
  temperature: number;
  maxTokens: number;
  rpmLimit: number;
}

